const T=h=>TILES.find(t=>t[0]===h)||MORE_EXTRA.find(t=>t[0]===h);
const homeGrid=()=>{const big=HOME_BIG.map(T),last=big.length%2?big.length-1:-1;
 return `<div class="fgrid hgrid" id="homeBig">${big.map(([h,i,e,u],k)=>`<a class="fcard${k===last?' wide':''}${k<2?' feat feat-'+i:''}" href="${h}">${I.corner}<span class="fi">${I.icon(i)}</span><b>${tt(e,u)}</b><small>${SUB[i]?tt(...SUB[i]):''}</small></a>`).join('')}</div>
 <div class="cgrid hsm" id="homeSm">${HOME_SM.map(T).map(([h,i,e,u])=>`<a class="ccard" href="${h}"><span class="fi">${I.icon(i)}</span><span>${tt(e,u)}</span></a>`).join('')}</div>
 <a class="hram" href="#/ramadan" id="homeRamadan"><span class="fi">${I.icon('ramadan')}</span><span><b>${tt('Ramadan','رمضان')}</b><small>${tt('Suhoor & iftar times, fasting log','سحری و افطار کے اوقات، روزوں کا ریکارڈ')}</small></span><span class="go">›</span></a>`};
const grid=list=>{const big=list.filter(x=>x[4]),sm=list.filter(x=>!x[4]);
 return `<div class="fgrid">${big.map(([h,i,e,u])=>`<a class="fcard" href="${h}">${I.corner}<span class="fi">${I.icon(i)}</span><b>${tt(e,u)}</b><small>${SUB[i]?tt(...SUB[i]):''}</small></a>`).join('')}</div>
 <div class="cgrid">${sm.map(([h,i,e,u])=>`<a class="ccard" href="${h}"><span class="fi">${I.icon(i)}</span><span>${tt(e,u)}</span></a>`).join('')}</div>`};
function nowPrayer(){const n=new Date(),pt=PR.times(n);let cur='isha';for(const k of PR.PRAYERS)if(pt[k]<=n)cur=k;return cur}
const PAR={fajr:'الفجر',sunrise:'الشروق',dhuhr:'الظهر',asr:'العصر',maghrib:'المغرب',isha:'العشاء'};
const PIC={fajr:'p-fajr',sunrise:'p-sunrise',dhuhr:'p-dhuhr',asr:'p-asr',maghrib:'p-maghrib',isha:'p-isha'};
/** Home prayer-times card: next prayer + countdown + progress, and a 6-prayer row with the current one emphasised. */
function pcard(nx0){const n=new Date(),pt=PR.times(n),cur=nowPrayer(),y=PR.times(new Date(n.getTime()-864e5)),hs=PR.headerState(pt,n,nx0);
 const mk=hs&&hs.mode==='makrooh',fj=hs&&hs.mode==='current',nx=hs&&!mk?{key:hs.key,time:hs.time}:null;
 const from=fj?hs.from:(pt[cur]<=n?pt[cur]:y[cur]),pct=nx?Math.max(0,Math.min(100,100*(n-from)/(nx.time-from))):0;
 const hl=fj?'fajr':mk?(hs.kind==='sunrise'?'sunrise':null):cur;
 const cell=k=>{const[t,ap]=PR.fmt12(pt[k]).split(' ');const st=k===hl?'cur':(nx&&!fj&&nx.key===k?'nx':(pt[k]<n&&k!==hl?'past':''));return `<div class="pc-i ${st}"><span class="pc-ic">${I.icon(PIC[k])}</span><b>${C.pn(k)}</b><span class="pc-t">${t}<small>${ap||''}</small></span></div>`};
 const MKN={sunrise:['After sunrise','طلوعِ آفتاب'],zawal:['Zawal','زوال'],sunset:['Before sunset','غروبِ آفتاب']};
 return `<a class="pcard${mk?' pc-mk':''}" href="#/prayer" id="homePrayer" aria-label="${tt('Prayer times','اوقاتِ نماز')}">${I.mosqueArt}
  <div class="pc-top"><span class="pc-badge"><i></i>${mk?tt('Makrooh time','مکروہ وقت'):fj?tt('Current prayer','موجودہ نماز'):nx?tt('Next prayer','اگلی نماز'):tt('Now','اب')+' · '+C.pn(cur)}</span><span class="pc-loc">${I.icon('pin')}${esc(PR.P.city||'')}</span></div>
  ${mk?`<div class="pc-main"><div class="pc-mkn" role="status"><b>${tt('Makrooh time — no sajda','مکروہ وقت — سجدہ منع ہے')}</b><small>${tt(MKN[hs.kind][0],MKN[hs.kind][1])} · ${tt('ends','ختم')} <bdi dir="ltr">${PR.fmt12(hs.until)}</bdi></small><span class="pc-cdw"><bdi dir="ltr" class="cd" data-at="${+hs.until}"></bdi><small>${tt('left','باقی')}</small></span></div></div>
  <div class="pc-bar" data-from="${+hs.from}" data-at="${+hs.until}"><i style="--w:${Math.max(0,Math.min(100,100*(n-hs.from)/(hs.until-hs.from))).toFixed(1)}%"></i></div>`:''}
  ${nx?`<div class="pc-main"><div class="pc-nx"><b>${C.pn(nx.key)}</b><bdi dir="ltr" class="pc-at">${PR.fmt12(fj?hs.from:nx.time)}</bdi><span class="pc-cdw"><bdi dir="ltr" class="cd" data-at="${+nx.time}"></bdi><small>${fj?tt('left · until sunrise','باقی · طلوع تک'):tt('left','باقی')}</small></span><span class="pc-arch" aria-hidden="true">${I.icon(PIC[nx.key])}<span class="ar" lang="ar" dir="rtl">${PAR[nx.key]}</span></span></div></div>
  <div class="pc-bar" data-from="${+from}" data-at="${+nx.time}"><i style="--w:${pct.toFixed(1)}%"></i></div>`:''}
  <div class="pc-row">${PR.PRAYERS.map(cell).join('')}</div></a>`}
export async function dashboard(){C.setTitle(tt('Quran Safar','قرآن سفر'));document.body.classList.add('is-home');const [AR,tr,list]=await Promise.all([C.arabic([L.ayahOfDay().s]),C.transFor(L.ayahOfDay().s),C.surahs()]);
 const {s,a}=L.ayahOfDay(),lr=LS.get('lastRead'),st=readStreak(),kp=LS.get('khatam');const nx=PR.next();const plan=kp?L.khatamPlan({current:kp.page,end:kp.end}):null;
 app().innerHTML=`<section class="hero">
  <div class="htop"><a class="round" href="#/more" aria-label="${tt('Menu','مینو')}">${I.icon('menu')}</a><div class="htitle"><b class="appname">${tt('Quran Safar','قرآن سفر')}</b><small><span data-greg="short">${DT.gregText(new Date(),S().ui,{weekday:'short',day:true,month:'short',year:true})}</span> · <span class="hij" data-hij>${PR.hijri(new Date(),S().ui)}</span><span data-hijsep> · </span><span class="streak" id="streak"><b>${st}</b> ${tt('day streak','دن مسلسل')}</span></small></div></div>
  ${pcard(nx)}
  <a class="hq-row" href="${lr?`#/surah/${lr.s}/${lr.a}`:'#/quran'}" id="homeQuran"><span class="ti hq-ti">${I.icon('quran')}</span><b>${tt('Quran','قرآن')}</b><small>${lr?`${tt('Continue','جاری')} ${lr.s}:${lr.a}`:tt('114 surahs','114 سورتیں')}</small></a>
  <div class="hcards"><a class="hc hc-tutor" href="#/recite" id="homeTutor"><span class="ti">${I.icon('tutor')}</span><span class="hc-live">● ${tt('LIVE','لائیو')}</span><b>${tt('Quran Live','قرآن لائیو')}</b><small>${tt('Recite & Learn','تلاوت اور سیکھیں')}</small></a>
  ${qaidaHomeCard(tt,I)}<a class="hc hc-hifz" href="#/hifztest" id="homeHifz"><span class="ti">${I.icon('hifz')}</span><span class="hc-live">● ${tt('LIVE','لائیو')}</span><b>${tt('Hifz Test','حفظ ٹیسٹ')}</b><small>${tt('Recite from memory','یاد سے سنائیں')}</small></a></div>
  ${(()=>{const n=dueItems(weakLoad()).length;return n?`<a class="tutor-card review" href="#/recite/review" id="homeReview"><span class="ti">★</span><div><b>${tt('Review weak words','کمزور الفاظ کی دہرائی')}</b><small>${tt(n+' word'+(n>1?'s':'')+' ready to practice',n+' الفاظ مشق کے لیے تیار')}</small></div><span class="go">›</span></a>`:''})()}
 </section>
 <section class="dsec">
 ${plan?`<a class="card kcard" href="#/khatam">${I.icon('khatam')} ${tt('Khatam','ختم')}: <b>${plan.pct}%</b> · ${tt('today','آج')} ${plan.perDay} ${tt('pages','صفحات')}<div class="prog"><i style="width:${plan.pct}%"></i></div></a>`:''}
 ${homeGrid()}
 <div class="card aotd" id="aotd">${I.corner}<small class="muted">${tt('Ayah of the day','آج کی آیت')} · ${esc(list[s-1].englishName)} ${s}:${a}</small><p class="ar" dir="rtl" lang="ar">${esc(L.ayahText(s,a,AR[s-1][a-1]))}</p><p class="tr" dir="${tr.edition.direction==='rtl'?'rtl':'ltr'}">${esc(tr.texts[a-1]||'')}</p>
 <div class="bar"><a class="btn" href="#/surah/${s}/${a}">${I.icon('quran')} ${tt('Open','کھولیں')}</a><button class="btn ghost" id="aShare">${I.icon('share')} ${tt('Share image','تصویر شیئر')}</button></div></div>
 </section>`;
 $('#aShare').onclick=()=>shareAyah(s,a);
C.tick()}
const MODEL_CACHE='qs-asr-model';
const modelHave=async()=>{if(LS.get('qsCtc',0)||localStorage.getItem('qsCtc'))return true;try{return !!(window.caches&&(await caches.has(MODEL_CACHE))&&(await (await caches.open(MODEL_CACHE)).keys()).length)}catch{return false}};
/** Two-tap confirm (no native dialogs): first tap arms the button for 4 s, second tap runs it. */
function twoTap(btn,sure,run){const o=btn.innerHTML;btn.onclick=()=>{if(btn.dataset.arm){run();return}btn.dataset.arm='1';btn.textContent=sure;btn.classList.add('danger');setTimeout(()=>{if(!btn.isConnected)return;delete btn.dataset.arm;btn.innerHTML=o;btn.classList.remove('danger')},4000)}}
